// Custom CUDA cumulative-sum (prefix scan) along a tensor dimension.
//
// Fast path (scanned dim is the innermost one): one thread block per row, the
// row is processed in rounds of 4*BLOCK contiguous elements using float4 loads
// and stores.  Each thread owns four consecutive elements, so the block-wide
// scan is: per-thread sequential prefix -> warp-level inclusive scan -> one
// shared-memory publication of the warp totals -> redundant per-warp scan of
// those totals (a single __syncthreads() per round).  The first few elements of
// a row are peeled off with scalar accesses so that the float4 body is 16-byte
// aligned even though the row length is odd.
//
// Fallbacks (never exercised by the task shapes, but required for correctness):
//   * rows whose input/output relative alignment differs -> scalar scan kernel
//   * scanned dim not innermost                          -> generic kernel

#include <cuda_runtime.h>

namespace {

constexpr int kBlock = 512;

__device__ __forceinline__ float warp_incl_scan(float v, int lane) {
#pragma unroll
    for (int off = 1; off < 32; off <<= 1) {
        const float n = __shfl_up_sync(0xffffffffu, v, off);
        if (lane >= off) v += n;
    }
    return v;
}

// ---------------------------------------------------------------------------
// Primary kernel: vectorised (float4) scan, one __syncthreads() per round.
// ---------------------------------------------------------------------------
template <int T>
__global__ __launch_bounds__(T) void cumsum_rows_vec4(const float* __restrict__ in,
                                                      float* __restrict__ out,
                                                      int L, long long rowStride) {
    constexpr int NW = T / 32;
    __shared__ float warpSums[NW];

    const long long row = blockIdx.x;
    const float* __restrict__ ip = in + row * rowStride;
    float* __restrict__ op = out + row * rowStride;

    const int t = threadIdx.x;
    const int lane = t & 31;
    const int warp = t >> 5;

    // Leading scalars needed before the row body is 16-byte aligned.
    int head = (int)((4u - (((unsigned)(uintptr_t)ip >> 2) & 3u)) & 3u);
    if (head > L) head = L;

    float carry = 0.f;
    if (head > 0) {
        const float h0 = ip[0];
        const float h1 = (head > 1) ? ip[1] : 0.f;
        const float h2 = (head > 2) ? ip[2] : 0.f;
        carry = h0 + h1 + h2;
        if (t == 0) {
            float acc = h0;
            op[0] = acc;
            if (head > 1) { acc += h1; op[1] = acc; }
            if (head > 2) { acc += h2; op[2] = acc; }
        }
    }

    const int nBody = ((L - head) >> 2) << 2;
    const float4* __restrict__ ip4 = (const float4*)(ip + head);
    float4* __restrict__ op4 = (float4*)(op + head);
    const int V = nBody >> 2;
    const int rounds = (V + T - 1) / T;
    const float4 zero4 = make_float4(0.f, 0.f, 0.f, 0.f);

    for (int r = 0; r < rounds; ++r) {
        const int g = r * T + t;
        const bool active = (g < V);
        const float4 v = active ? ip4[g] : zero4;

        const float s0 = v.x;
        const float s1 = s0 + v.y;
        const float s2 = s1 + v.z;
        const float s3 = s2 + v.w;

        const float incl = warp_incl_scan(s3, lane);
        if (lane == 31) warpSums[warp] = incl;
        __syncthreads();

        // Every warp redundantly scans the published warp totals; lane `warp`
        // then holds this warp's exclusive block offset.
        const float wv = (lane < NW) ? warpSums[lane] : 0.f;
        const float inc = warp_incl_scan(wv, lane);
        const float ex = inc - wv;
        const float myOff = __shfl_sync(0xffffffffu, ex, warp);
        const float blkTot = __shfl_sync(0xffffffffu, inc, NW - 1);

        // Exclusive offset of this thread's first element.
        const float b = carry + myOff + (incl - s3);
        carry += blkTot;

        if (active) {
            float4 res;
            res.x = b + s0;
            res.y = b + s1;
            res.z = b + s2;
            res.w = b + s3;
            op4[g] = res;
        }
        if (r + 1 < rounds) __syncthreads();
    }

    // Trailing scalars (< 4 elements) after the vectorised body.
    const int tailStart = head + nBody;
    if (t == 0 && tailStart < L) {
        float acc = carry;
        for (int i = tailStart; i < L; ++i) {
            acc += ip[i];
            op[i] = acc;
        }
    }
}

// ---------------------------------------------------------------------------
// Fallback A: scalar, coalesced, one block-wide scan per tile of T elements.
// Used only when input and output have different 16-byte alignment.
// ---------------------------------------------------------------------------
template <int T>
__global__ __launch_bounds__(T) void cumsum_rows_scalar(const float* __restrict__ in,
                                                        float* __restrict__ out,
                                                        int L, long long rowStride) {
    constexpr int NW = T / 32;
    __shared__ float warpSums[NW];

    const long long row = blockIdx.x;
    const float* __restrict__ ip = in + row * rowStride;
    float* __restrict__ op = out + row * rowStride;

    const int t = threadIdx.x;
    const int lane = t & 31;
    const int warp = t >> 5;

    float carry = 0.f;
    int base = 0;
    for (; base < L; base += T) {
        const int rem = L - base;
        const float v = (t < rem) ? ip[base + t] : 0.f;
        const float s = warp_incl_scan(v, lane);
        if (lane == 31) warpSums[warp] = s;
        __syncthreads();
        float off = carry;
        float tot = carry;
#pragma unroll
        for (int w = 0; w < NW; ++w) {
            const float ws = warpSums[w];
            if (w < warp) off += ws;
            tot += ws;
        }
        carry = tot;
        if (t < rem) op[base + t] = s + off;
        __syncthreads();
    }
}

// ---------------------------------------------------------------------------
// Fallback B: the scanned dimension is not the innermost one.
// ---------------------------------------------------------------------------
__global__ void cumsum_generic(const float* __restrict__ in,
                               float* __restrict__ out,
                               long long outer, long long len, long long inner) {
    const long long total = outer * inner;
    for (long long col = blockIdx.x * (long long)blockDim.x + threadIdx.x; col < total;
         col += (long long)gridDim.x * blockDim.x) {
        const long long o = col / inner;
        const long long i = col - o * inner;
        const float* __restrict__ ip = in + o * len * inner + i;
        float* __restrict__ op = out + o * len * inner + i;
        float acc = 0.f;
        for (long long k = 0; k < len; ++k) {
            acc += ip[k * inner];
            op[k * inner] = acc;
        }
    }
}

}  // namespace

extern "C" void launch_cumsum_lastdim(const float* in, float* out, long long outer,
                                      long long len, long long inner,
                                      cudaStream_t stream) {
    if (outer <= 0 || len <= 0) return;

    if (inner != 1 || len > 2147483647LL) {
        const int threads = 128;
        const long long cols = outer * inner;
        long long blocks = (cols + threads - 1) / threads;
        if (blocks > 65535) blocks = 65535;
        if (blocks < 1) blocks = 1;
        cumsum_generic<<<(unsigned)blocks, threads, 0, stream>>>(in, out, outer, len, inner);
        return;
    }

    const unsigned grid = (unsigned)outer;
    const int L = (int)len;

    // The float4 kernel needs input and output to share the same 16-byte
    // relative alignment (true for allocations from the caching allocator).
    if (((uintptr_t)in & 15u) == ((uintptr_t)out & 15u)) {
        cumsum_rows_vec4<kBlock><<<grid, kBlock, 0, stream>>>(in, out, L, len);
    } else {
        cumsum_rows_scalar<256><<<grid, 256, 0, stream>>>(in, out, L, len);
    }
}

