#include <torch/types.h>
#include <torch/csrc/utils/pybind.h>
#include <ATen/ops/empty_like.h>

#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include "../binding_registry.h"

extern "C" void launch_cumsum_lastdim(const float* in, float* out, long long outer,
                                      long long len, long long inner,
                                      cudaStream_t stream);

// Cumulative sum of a contiguous float32 CUDA tensor along `dim`.
// `outer` = product of the dims before `dim`, `inner` = product of the dims
// after it; the kernel scans `len` = size(dim) elements for each of the
// `outer * inner` independent columns.
static torch::Tensor cumsum_forward(const torch::Tensor& x, int64_t dim) {
    TORCH_CHECK(x.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(x.is_contiguous(), "input must be contiguous");

    const int64_t nd = x.dim();
    int64_t d = dim;
    if (d < 0) d += nd;
    TORCH_CHECK(nd >= 1 && d >= 0 && d < nd, "invalid dim");

    long long outer = 1, inner = 1;
    const long long len = (long long)x.size(d);
    for (int64_t i = 0; i < d; ++i) outer *= (long long)x.size(i);
    for (int64_t i = d + 1; i < nd; ++i) inner *= (long long)x.size(i);

    torch::Tensor out = at::empty_like(x);
    if (x.numel() == 0) return out;

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    launch_cumsum_lastdim(x.data_ptr<float>(), out.data_ptr<float>(), outer, len, inner,
                          stream);
    return out;
}

static void register_cumsum(pybind11::module& m) {
    m.def("cumsum_forward", &cumsum_forward, "cumulative sum along dim",
          pybind11::arg("x"), pybind11::arg("dim") = 1);
}

REGISTER_BINDING(cumsum, register_cumsum);
